{
  "root": "main_stack",
  "state": {
    "itinerary": [
      {
        "day": "Day 1",
        "title": "Fushimi Inari Sunrise",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Fushimi_Inari-taisha_shrine_in_Kyoto.jpg/1200px-Fushimi_Inari-taisha_shrine_in_Kyoto.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/camera.svg",
        "morning": "Morning: 06:00 start at Fushimi Inari-taisha for the thousand torii gates in soft light.",
        "afternoon": "Afternoon: Tofuku-ji Temple gardens for early autumn foliage shots.",
        "evening": "Evening: Gion district during blue hour for atmospheric street photography.",
        "actionLabel": "Fushimi Inari Info",
        "actionUrl": "https://www.inari.jp/en/"
      },
      {
        "day": "Day 2",
        "title": "Arashiyama Morning Light",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Arashiyama_Bamboo_Grove_Kyoto_Japan.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto_Japan.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "morning": "Morning: Early visit to the Bamboo Grove to capture the light filtering through the stalks.",
        "afternoon": "Afternoon: Tenryu-ji Temple Zen garden and its reflection pond.",
        "evening": "Evening: Scenic walk along the Katsura River for sunset vistas.",
        "actionLabel": "Arashiyama Guide",
        "actionUrl": "https://www.japan-guide.com/e/e3912.html"
      }
    ],
    "budget": [
      {
        "category": "Accommodation",
        "totalCost": "$800",
        "dailyAverage": "$160 (Stay near Kyoto Station)"
      },
      {
        "category": "Food & Dining",
        "totalCost": "$600",
        "dailyAverage": "$120 (Street food & mid-range)"
      },
      "Transit",
      {
        "category": "Transit",
        "totalCost": "$150",
        "dailyAverage": "$30 (Kyoto Bus/Subway Pass)"
      },
      {
        "category": "Entry Fees",
        "totalCost": "$200",
        "dailyAverage": "$40 (Temples & Gardens)"
      },
      {
        "category": "Total",
        "totalCost": "$1,750",
        "dailyAverage": "Within $1,800 Budget"
      }
    ],
    "tips": [
      "Soft Focus: Use a wide aperture (f/2.8 or lower) to create a soft, dreamy background for delicate petals.",
      "Contrast: Capture falling petals against dark temple wood or deep green moss for visual impact.",
      "Golden Hour: Shoot during the final hour of daylight for a warm glow that enhances the pink hues."
    ],
    "quickActions": [
      {
        "label": "Kyoto Transit Map",
        "url": "https://www.city.kyoto.lg.jp/kotsu/category/166-0-0-0-0-0-0-0-0-0.html"
      },
      {
        "label": "Best Photo Spots",
        "url": "https://www.kyotophotography.com/best-photo-spots-kyoto/"
      }
    ],
    "sources": [
      {
        "label": "Kyoto Tourism",
        "url": "https://kyoto.travel/en/"
      },
      {
        "label": "Japan Guide",
        "url": "https://www.japan-guide.com/"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_kyoto_expedition",
        "subtitle_itinerary",
        "itinerary_cards_stack",
        "budget_title",
        "budget_table",
        "tips_title",
        "tips_stack",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title_kyoto_expedition": {
      "type": "Text",
      "props": {
        "text": "Kyoto Photography Expedition",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle_itinerary": {
      "type": "Text",
      "props": {
        "text": "5-Day Visual Heritage Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_cards_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "itinerary_card_template"
      ]
    },
    "itinerary_card_template": {
      "type": "Card",
      "repeat": {
        "statePath": "/itinerary",
        "key": "day"
      },
      "props": {},
      "children": [
        "day_header_stack",
        "day_image",
        "day_details_stack",
        "day_action_button"
      ]
    },
    "day_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "justify": "between",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day_title",
        "day_icon"
      ]
    },
    "day_title": {
      "type": "Text",
      "props": {
        "text": "{ \"$template\": \"${$item.day}: ${$item.title}\" }"
      },
      "children": []
    },
    "day_icon": {
      "type": "Icon",
      "props": {
        "name": "{ \"$item\": \"icon\" }"
      },
      "children": []
    },
    "day_image": {
      "type": "Image",
      "props": {
        "url": "{ \"$item\": \"image\" }",
        "fit": "cover"
      },
      "children": []
    },
    "day_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "day_morning_text",
        "day_afternoon_text",
        "day_evening_text"
      ]
    },
    "day_morning_text": {
      "type": "Text",
      "props": {
        "text": "{ \"$item\": \"morning\" }"
      },
      "children": []
    },
    "day_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "{ \"$item\": \"afternoon\" }"
      },
      "children": []
    },
    "day_evening_text": {
      "type": "Text",
      "props": {
        "text": "{ \"$item\": \"evening\" }"
      },
      "children": []
    },
    "day_action_button": {
      "type": "Button",
      "props": {
        "label": "{ \"$item\": \"actionLabel\" }"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "{ \"$item\": \"actionUrl\" }"
          }
        }
      },
      "children": []
    },
    "budget_title": {
      "type": "Text",
      "props": {
        "text": "Estimated Budget Breakdown (2 Adults)",
        "variant": "h2"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "totalCost",
            "label": "Total Cost (USD)"
          },
          {
            "key": "dailyAverage",
            "label": "Daily Average"
          }
        ],
        "statePath": "/budget",
        "domain": "comparison",
        "preferredPresentation": "table",
        "numericColumns": [
          "totalCost",
          "dailyAverage"
        ]
      },
      "children": []
    },
    "tips_title": {
      "type": "Text",
      "props": {
        "text": "Cherry Blossom Photography Tips",
        "variant": "h2"
      },
      "children": []
    },
    "tips_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "tip_1",
        "tip_2",
        "tip_3"
      ]
    },
    "tip_1": {
      "type": "Text",
      "props": {
        "text": "{ \"$state\": \"/tips/0\" }"
      },
      "children": []
    },
    "tip_2": {
      "type": "Text",
      "props": {
        "text": "{ \"$state\": \"/tips/1\" }"
      },
      "children": []
    },
    "tip_3": {
      "type": "Text",
      "props": {
        "text": "{ \"$state\": \"/tips/2\" }"
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_action_button_1",
        "quick_action_button_2"
      ]
    },
    "quick_action_button_1": {
      "type": "Button",
      "props": {
        "label": "{ \"$state\": \"/quickActions/0/label\" }"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "{ \"$state\": \"/quickActions/0/url\" }"
          }
        }
      },
      "children": []
    },
    "quick_action_button_2": {
      "type": "Button",
      "props": {
        "label": "{ \"$state\": \"/quickActions/1/label\" }"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "{ \"$state\": \"/quickActions/1/url\" }"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_button_1",
        "source_button_2"
      ]
    },
    "source_button_1": {
      "type": "Button",
      "props": {
        "label": "{ \"$state\": \"/sources/0/label\" }"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "{ \"$state\": \"/sources/0/url\" }"
          }
        }
      },
      "children": []
    },
    "source_button_2": {
      "type": "Button",
      "props": {
        "label": "{ \"$state\": \"/sources/1/label\" }"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "{ \"$state\": \"/sources/1/url\" }"
          }
        }
      },
      "children": []
    }
  }
}
